/* RISC-V host program: load a CGRA kernel, run it, check the result.
 * kernel.h is generated by scripts/cgra_image.py from a pace-sim kernel
 * folder; dm_fnv_expected[] are checksums of pace-sim's final memories. */
#include <stdint.h>
#include "pace_cgra.h"
#include "kernel.h"

#define CON (*(volatile uint32_t *)0x20000000u)
static void puts_(const char *s) { while (*s) CON = (uint32_t)*s++; }
static void puthex(uint32_t v) {
    for (int i = 28; i >= 0; i -= 4) CON = (uint32_t)"0123456789abcdef"[(v >> i) & 15];
}
static void putdec(uint32_t v) {
    char b[11]; int i = 10; b[i] = 0;
    do { b[--i] = (char)('0' + v % 10); v /= 10; } while (v);
    puts_(&b[i]);
}

int main(void) {
    puts_("RISC-V host: CGRA id = 0x"); puthex(CGRA_REG(CGRA_ID)); puts_("\n");

    /* 1. configure: PE config memories, AGU programs, input data */
    cgra_load_image(img, IMG_N);
    puts_("  loaded "); putdec(IMG_N); puts_(" config/data words over the bus\n");

    /* 2. run: interrupt enabled, then START; poll STATUS until not busy */
    CGRA_REG(CGRA_IRQ_EN) = 1;
    cgra_start();
    uint32_t st = cgra_wait();
    puts_("  CGRA finished: status=0x"); puthex(st);
    puts_(" cycles="); putdec(CGRA_REG(CGRA_CYCLES)); puts_("\n");

    /* 3. read back all 8 data memories and compare with pace-sim */
    int errors = 0;
    for (unsigned d = 0; d < 8; d++) {
        uint32_t h = 0x811C9DC5u;
        for (unsigned b = 0; b < 8192; b += 4)
            h = (h ^ CGRA_REG(CGRA_DM(d, b))) * 0x01000193u;
        int ok = (h == dm_fnv_expected[d]);
        errors += !ok;
        puts_("  DM"); putdec(d); puts_(" fnv=0x"); puthex(h);
        puts_(ok ? "  match\n" : "  MISMATCH\n");
    }
    puts_(errors ? "RESULT: FAIL\n" : "RESULT: PASS (CGRA output == pace-sim)\n");
    return errors;
}
